def create_invoices_for_existing_orders(apps, schema_editor):
    Order = apps.get_model("orders", "Order")
    OrderItem = apps.get_model("orders", "OrderItem")
    Payment = apps.get_model("orders", "Payment")
    Invoice = apps.get_model("orders", "Invoice")

    def quantize(value):
        return Decimal(value).quantize(Decimal("0.01"))

    for order in Order.objects.all().iterator():
        if Invoice.objects.filter(order_id=order.pk).exists():
            continue

        items = OrderItem.objects.filter(order_id=order.pk)
        subtotal = sum((item.price * item.quantity for item in items), Decimal("0.00"))
        subtotal = quantize(subtotal)
        tax = quantize(subtotal * Decimal("0.18"))
        total_amount = quantize(order.total or Decimal("0.00"))
        shipping_cost = total_amount - subtotal - tax
        if shipping_cost < Decimal("0.00"):
            shipping_cost = Decimal("0.00")
        shipping_cost = quantize(shipping_cost)

        latest_payment = Payment.objects.filter(order_id=order.pk).order_by("-created_at", "-id").first()
        payment_status = latest_payment.status if latest_payment else (order.payment_status or "Pending")

        Invoice.objects.create(
            invoice_number=f"INV-{order.pk:08d}",
            order_id=order.pk,
            user_id=order.user_id,
            subtotal=subtotal,
            tax=tax,
            shipping_cost=shipping_cost,
            total_amount=total_amount,
            payment_status=payment_status,
            created_at=order.created_at,
        )


